.light{--primary:#2F5BC7;--onPrimary:#FFFFFF;--primaryContainer:#DAE2FF;--onPrimaryContainer:#001848;--secondary:#575E71;--secondaryContainer:#DCE2F9;--onSecondaryContainer:#141B2C;--tertiary:#715573;--tertiaryContainer:#FCD7FB;--background:#FAF8FF;--surface:#FAF8FF;--surfaceContainerLow:#F4F3FA;--surfaceContainer:#EEEDF4;--surfaceContainerHigh:#E8E7EF;--surfaceContainerHighest:#E2E2E9;--onSurface:#1A1B21;--onSurfaceVariant:#44464F;--outline:#757780;--outlineVariant:#C5C6D0;--error:#BA1A1A;--illo1:#E8ECF8;--illo2:#C7CFE4;--illo3:#8F9AB5;}.dark{--primary:#B2C5FF;--onPrimary:#002B73;--primaryContainer:#1A43A6;--onPrimaryContainer:#DAE2FF;--secondary:#C0C6DC;--secondaryContainer:#404659;--onSecondaryContainer:#DCE2F9;--tertiary:#DEBCDF;--tertiaryContainer:#583E5B;--background:#121318;--surface:#121318;--surfaceContainerLow:#1A1B21;--surfaceContainer:#1E1F25;--surfaceContainerHigh:#292A2F;--surfaceContainerHighest:#33343A;--onSurface:#E3E2E9;--onSurfaceVariant:#C5C6D0;--outline:#8F9099;--outlineVariant:#44464F;--error:#FFB4AB;--illo1:#23262F;--illo2:#3A3F4D;--illo3:#6B7488;}
.board{display:flex;gap:32px;flex-wrap:wrap;justify-content:center;padding:24px;font-family:Roboto,'Segoe UI',Arial,sans-serif;background:#d9dbe1}
.col{display:flex;flex-direction:column;align-items:center;gap:8px}
.cap{font:600 13px/1.2 Roboto,Arial;color:#333;letter-spacing:.3px}
.phone{width:360px;height:760px;border-radius:28px;overflow:hidden;position:relative;background:var(--background);color:var(--onSurface);
 box-shadow:0 8px 30px rgba(0,0,0,.25);border:8px solid #111;display:flex;flex-direction:column}
.status{height:24px;background:var(--surface);color:var(--onSurface);font-size:12px;display:flex;justify-content:space-between;padding:4px 16px;box-sizing:border-box}
.tb{height:64px;background:var(--surface);display:flex;align-items:center;padding:0 4px 0 8px;gap:4px}
.tb .ic{width:48px;height:48px;display:flex;align-items:center;justify-content:center;color:var(--onSurfaceVariant);font-size:22px;border-radius:24px;cursor:pointer}
.tb .ttl{flex:1;display:flex;flex-direction:column;padding-left:8px}
.tb .t{font-size:22px;color:var(--onSurface)}
.tb .st{font-size:14px;color:var(--onSurfaceVariant);cursor:pointer}
.content{flex:1;position:relative;overflow:hidden;background:var(--surface)}
.dots{display:flex;gap:8px;justify-content:center;padding:6px 0 10px}
.dots i{width:8px;height:8px;border-radius:4px;border:1px solid var(--primary)}
.dots i.on{background:var(--primary);width:22px}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px 4px;padding:12px 8px}
.app{display:flex;flex-direction:column;align-items:center;gap:6px;position:relative;cursor:pointer}
.icon{width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:18px}
.lbl{font-size:12px;color:var(--onSurface);text-align:center;max-width:78px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.badge{position:absolute;top:-2px;right:10px;background:var(--tertiaryContainer);color:var(--tertiary);font-size:9px;font-weight:700;padding:1px 4px;border-radius:6px}
.fab{position:absolute;right:16px;bottom:16px;width:56px;height:56px;border-radius:16px;background:var(--primaryContainer);color:var(--onPrimaryContainer);
 display:flex;align-items:center;justify-content:center;font-size:30px;box-shadow:0 3px 6px rgba(0,0,0,.25);cursor:pointer}
.empty{display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;gap:16px;color:var(--onSurfaceVariant)}
.illo{width:150px;height:150px;border-radius:75px;background:var(--illo1);display:flex;align-items:center;justify-content:center}
.illo div{width:70px;height:84px;border-radius:8px;background:var(--illo2);border:3px solid var(--illo3)}
.row{display:flex;align-items:center;gap:16px;padding:10px 16px;min-height:72px;box-sizing:border-box}
.row .tx{flex:1;display:flex;flex-direction:column;gap:2px;min-width:0}
.row .a{font-size:16px;color:var(--onSurface)}
.row .b{font-size:14px;color:var(--onSurfaceVariant);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.search{margin:8px 12px;height:56px;border-radius:28px;background:var(--surfaceContainerHigh);display:flex;align-items:center;gap:12px;padding:0 16px;color:var(--onSurfaceVariant)}
.search .q{flex:1;color:var(--onSurface)}
.search .cur{display:inline-block;width:2px;height:18px;background:var(--primary);vertical-align:middle}
.cat{font-size:14px;font-weight:500;color:var(--primary);padding:20px 16px 6px 72px}
.pref{display:flex;align-items:center;gap:16px;padding:14px 16px;min-height:56px;box-sizing:border-box;cursor:pointer}
.pref .pi{width:40px;text-align:center;color:var(--onSurfaceVariant);font-size:20px}
.pref .tx{flex:1;display:flex;flex-direction:column;gap:2px}
.pref .a{font-size:16px;color:var(--onSurface)}
.pref .b{font-size:14px;color:var(--onSurfaceVariant)}
.sw{width:52px;height:32px;border-radius:16px;box-sizing:border-box;position:relative;flex:none}
.sw.off{background:var(--surfaceContainerHighest);border:2px solid var(--outline)}
.sw.off::after{content:'';position:absolute;left:6px;top:6px;width:16px;height:16px;border-radius:8px;background:var(--outline)}
.sw.on{background:var(--primary)}
.sw.on::after{content:'✓';position:absolute;right:4px;top:4px;width:24px;height:24px;border-radius:12px;background:var(--onPrimary);color:var(--primary);font-size:14px;display:flex;align-items:center;justify-content:center}
.scrim{position:absolute;inset:0;background:rgba(0,0,0,.32);display:flex;align-items:center;justify-content:center}
.dlg{width:300px;background:var(--surfaceContainerHigh);border-radius:28px;padding:24px;box-sizing:border-box;color:var(--onSurface)}
.dlg h3{margin:0 0 16px;font:400 24px/1.3 Roboto,Arial}
.dlg p{margin:0 0 20px;font-size:14px;line-height:20px;color:var(--onSurfaceVariant)}
.btns{display:flex;justify-content:flex-end;gap:8px}
.btn{color:var(--primary);font-size:14px;font-weight:500;padding:10px 12px;border-radius:20px;cursor:pointer}
.radio{display:flex;align-items:center;gap:16px;padding:12px 0;font-size:16px}
.rb{width:20px;height:20px;border-radius:10px;border:2px solid var(--onSurfaceVariant);box-sizing:border-box;position:relative}
.rb.on{border-color:var(--primary)}
.rb.on::after{content:'';position:absolute;inset:3px;border-radius:6px;background:var(--primary)}
.field{border:1px solid var(--outline);border-radius:4px;padding:14px 16px;font-size:16px;position:relative;margin-bottom:20px}
.field.focus{border:2px solid var(--primary)}
.field span{position:absolute;top:-9px;left:12px;background:var(--surfaceContainerHigh);padding:0 4px;font-size:12px;color:var(--primary)}
.menu{position:absolute;background:var(--surfaceContainer);border-radius:4px;box-shadow:0 3px 8px rgba(0,0,0,.3);padding:8px 0;width:200px}
.menu div{padding:0 12px;height:48px;display:flex;align-items:center;font-size:14px;color:var(--onSurface)}
.splash{flex:1;display:flex;align-items:center;justify-content:center;background:var(--background)}
.logo{width:96px;height:96px;border-radius:24px;background:#3F3F3F;display:flex;align-items:center;justify-content:center;color:#fff;font:700 40px Roboto,Arial}
.map{height:300px;background:repeating-linear-gradient(0deg,#e8e4da 0 38px,#fff 38px 40px),#e8e4da;position:relative;border-bottom:1px solid var(--outlineVariant)}
.map::after{content:'📍';position:absolute;left:46%;top:40%;font-size:30px}
.note{font-size:12px;color:var(--onSurfaceVariant);padding:8px 16px}
.nav{height:24px;background:var(--surface)}

